package com.robotkinematicslab.mobile.dataset

import com.robotkinematicslab.mobile.diagnostics.benchmark.DiagnosticJointMode
import com.robotkinematicslab.mobile.diagnostics.benchmark.DiagnosticRobotFactory
import com.robotkinematicslab.mobile.domain.JointType

class DatasetRobotPresets(
    private val robotFactory: DiagnosticRobotFactory = DiagnosticRobotFactory()
) {

    /** Mathematical fixtures generated by DiagnosticRobotFactory; none is a commercial robot. */
    val syntheticPresetIds: Set<String>
        get() = SYNTHETIC_PRESET_IDS

    fun buildDefaults(): List<SavedRobot> {
        return listOf(
            preset("preset-02-revolute", 2, DiagnosticJointMode.REVOLUTE_ONLY, 0.10),
            preset("preset-03-revolute", 3, DiagnosticJointMode.REVOLUTE_ONLY, 0.25),
            preset("preset-04-revolute", 4, DiagnosticJointMode.REVOLUTE_ONLY, 0.40),
            preset("preset-04-prismatic", 4, DiagnosticJointMode.PRISMATIC_ONLY, 0.40),
            preset("preset-05-mixed", 5, DiagnosticJointMode.MIXED, 0.50),
            preset("preset-06-auto", 6, DiagnosticJointMode.AUTO, 0.55),
            preset("preset-06-revolute", 6, DiagnosticJointMode.REVOLUTE_ONLY, 0.60),
            preset("preset-06-mixed", 6, DiagnosticJointMode.MIXED, 0.65),
            preset("preset-08-auto", 8, DiagnosticJointMode.AUTO, 0.75),
            preset("preset-10-mixed", 10, DiagnosticJointMode.MIXED, 0.85)
        )
    }

    private fun preset(
        id: String,
        linkCount: Int,
        jointMode: DiagnosticJointMode,
        stressLevel: Double
    ): SavedRobot {
        val generated =
            robotFactory.buildSeedRobot(
                linkCount = linkCount,
                jointMode = jointMode,
                stressLevel = stressLevel
            )

        val readableMode =
            when (jointMode) {
                DiagnosticJointMode.AUTO -> "Auto"
                DiagnosticJointMode.REVOLUTE_ONLY -> "Revolute"
                DiagnosticJointMode.PRISMATIC_ONLY -> "Prismatic"
                DiagnosticJointMode.MIXED -> "Mixed"
            }

        return SavedRobot(
            id = id,
            robot = generated.copy(
                name = "Synthetic $linkCount-link $readableMode mathematical preset",
                dhParameters =
                    generated.dhParameters.mapIndexed { index, dh ->
                        if (generated.joints[index].type == JointType.PRISMATIC) {
                            dh.copy(d = 0.0)
                        } else {
                            dh
                        }
                    }
            )
        )
    }

    companion object {
        val SYNTHETIC_PRESET_IDS: Set<String> =
            setOf(
                "preset-02-revolute",
                "preset-03-revolute",
                "preset-04-revolute",
                "preset-04-prismatic",
                "preset-05-mixed",
                "preset-06-auto",
                "preset-06-revolute",
                "preset-06-mixed",
                "preset-08-auto",
                "preset-10-mixed"
            )

        fun isSyntheticPresetId(id: String): Boolean = id in SYNTHETIC_PRESET_IDS
    }
}
